const texCanvas=document.createElement('canvas');texCanvas.width=texCanvas.height=512;const ctx=texCanvas.getContext('2d');ctx.fillStyle='#77796a';ctx.fillRect(0,0,512,512);for(let i=0;i<35000;i++){const v=55+Math.floor(random()*105);ctx.fillStyle=`rgba(${v},${v+3},${v-6},${random()*.45})`;const x=random()*512,y=random()*512;ctx.fillRect(x,y,random()*3+1,random()*2+1);}for(let i=0;i<130;i++){ctx.strokeStyle=`rgba(30,35,25,${random()*.3})`;ctx.lineWidth=random()*1.7;ctx.beginPath();const x=random()*512,y=random()*512;ctx.moveTo(x,y);ctx.lineTo(x+random()*70-35,y+random()*120);ctx.stroke();}const stoneMap=new THREE.CanvasTexture(texCanvas);stoneMap.colorSpace=THREE.SRGBColorSpace;stoneMap.wrapS=stoneMap.wrapT=THREE.RepeatWrapping;
