const body=mesh(new THREE.CylinderGeometry(.54,.79,2.82,6,18),stone,0,.17);body.rotation.y=Math.PI/6;const pos=body.geometry.attributes.position;for(let i=0;i<pos.count;i++){const y=pos.getY(i);const n=.012*Math.sin(pos.getX(i)*34+y*19+pos.getZ(i)*23);pos.setXYZ(i,pos.getX(i)*(1+n),y,pos.getZ(i)*(1+n));}body.geometry.computeVertexNormals();
mesh(new THREE.CylinderGeometry(.61,.61,.13,6),bronze,0,1.64).rotation.y=Math.PI/6;mesh(new THREE.CylinderGeometry(.74,.78,.13,6),bronze,0,-1.08).rotation.y=Math.PI/6;
