for(let i=0;i<30;i++){const a=i*Math.PI*2/30;const t=mesh(new THREE.BoxGeometry(.027,.014,.17),i%5===0?ink:bronze,Math.sin(a)*1.47,-1.537,Math.cos(a)*1.47);t.rotation.y=a;}
for(let i=0;i<6;i++){const a=i*Math.PI/3+Math.PI/6;const rib=mesh(new THREE.CylinderGeometry(.028,.044,2.63,5),bronze,Math.sin(a)*.66,.2,Math.cos(a)*.66);rib.rotation.z=-Math.sin(a)*.068;rib.rotation.x=Math.cos(a)*.068;}
function glyphTexture(ids){const c=document.createElement('canvas');c.width=256;c.height=768;const x=c.getContext('2d');x.clearRect(0,0,256,768);x.strokeStyle='#edc98b';x.lineWidth=1.7;x.lineCap='round';x.lineJoin='round';for(let n=0;n<ids.length;n++){x.save();x.translate(57,80+n*215);x.scale(5,5);x.stroke(new Path2D(paths[ids[n]]));x.restore();}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t;}
const panels=[];[[0,1,2],[3,1,2],[4,5,2]].forEach((ids,i)=>{const a=i*Math.PI*2/3;const group=new THREE.Group();group.position.set(Math.sin(a)*.652,.23,Math.cos(a)*.652);group.rotation.y=a;const slab=new THREE.Mesh(new THREE.PlaneGeometry(.46,2.02),darkStone);group.add(slab);const face=new THREE.Mesh(new THREE.PlaneGeometry(.4,1.84),new THREE.MeshBasicMaterial({map:glyphTexture(ids),transparent:true,side:THREE.DoubleSide,opacity:i===0?1:.42}));face.position.z=.008;group.add(face);relic.add(group);panels.push(face);});
// Three inspection points link spatial exploration with the same accessible evidence controls.
const markers=[];for(let i=0;i<3;i++){const a=i*Math.PI*2/3;const marker=mesh(new THREE.SphereGeometry(.065,16,12),ink,Math.sin(a)*1.13,-.63,Math.cos(a)*1.13);marker.userData.site=i;markers.push(marker);const line=new THREE.Mesh(new THREE.TorusGeometry(.115,.006,4,36),ink);line.position.copy(marker.position);line.rotation.y=a;relic.add(line);}
