const dustCount=90;const dustPos=new Float32Array(dustCount*3);for(let i=0;i<dustCount;i++){dustPos[i*3]=(random()-.5)*7;dustPos[i*3+1]=(random()-.5)*6;dustPos[i*3+2]=(random()-.5)*5;}const dustGeo=new THREE.BufferGeometry();dustGeo.setAttribute('position',new THREE.BufferAttribute(dustPos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0xddd1a9,size:.013,transparent:true,opacity:.38,depthWrite:false}));scene.add(dust);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let drag=false,moved=false,startX=0,startY=0,manual=false,last=0;
