document.querySelector('#rotate-left').addEventListener('click',()=>rotate(-Math.PI/3));document.querySelector('#rotate-right').addEventListener('click',()=>rotate(Math.PI/3));
host.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag=true;moved=false;startX=e.clientX;startY=e.clientY;manual=true;host.setPointerCapture(e.pointerId);});host.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-startX,dy=e.clientY-startY;if(Math.abs(dx)+Math.abs(dy)>3)moved=true;targetYaw+=dx*.009;pitch=THREE.MathUtils.clamp(pitch+dy*.003,-.15,.7);startX=e.clientX;startY=e.clientY;render();});const ray=new THREE.Raycaster();host.addEventListener('pointerup',e=>{drag=false;if(!moved){const r=host.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(markers);if(hit.length)document.querySelector(`[data-site="${hit[0].object.userData.site}"]`).click();}});host.addEventListener('pointercancel',()=>drag=false);host.addEventListener('wheel',e=>{if(innerWidth<=760&&!e.ctrlKey)return;e.preventDefault();distance=THREE.MathUtils.clamp(distance+e.deltaY*.008,6.8,13);manual=true;render();},{passive:false});host.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')rotate(-.3);if(e.key==='ArrowRight')rotate(.3);if(e.key==='ArrowUp')pitch=Math.min(.7,pitch+.1);if(e.key==='ArrowDown')pitch=Math.max(-.15,pitch-.1);if(e.key==='+'||e.key==='=')distance=Math.max(6.8,distance-.5);if(e.key==='-')distance=Math.min(13,distance+.5);render();});
