function render(t=0){const dt=Math.min((t-last)/1000,.05);last=t;if(!reduced.matches&&!manual)targetYaw+=Math.max(0,dt)*.045;yaw=reduced.matches?targetYaw:THREE.MathUtils.lerp(yaw,targetYaw,.13);relic.rotation.y=yaw;camera.position.set(0,1+Math.sin(pitch)*distance,distance*Math.cos(pitch));camera.lookAt(0,.22,0);if(!reduced.matches){core.rotation.y+=Math.max(0,dt)*.13;core.position.y=2.02+Math.sin(t*.0007)*.035+awake*.3;dust.rotation.y=t*.000008;}else core.position.y=2.02+awake*.3;glow.intensity=4+awake*9;renderer.render(scene,camera);}
